<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{Principal,AccessGrant};use Hostider\Services\{Engine,Worker,Policies,PackageChanges,Runner};use Hostider\Hosting\Pools;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();
function packageFixture($db): array
{
    $f=serviceFixture($db);$pools=new Pools($db,$f['config']);$pool=$pools->configure($f['product']);$engine=new Engine($db,$f['config']);$id=$engine->discover($f['order']['id'],$f['actor'],Id::uuid())[0];(new Worker($db,$f['config']))->once($f['actor'],$engine->repository->find($id,lock:false)['current_operation_id']);$staff=new Principal('package-operator',['services.package','services.policy','services.reconcile'],staff:true,mfa:true,expiresAt:time()+3600,verifiedAt:time(),grants:[new AccessGrant('services.package',[$f['customer']],[$id]),new AccessGrant('services.reconcile',[$f['customer']],[$id])],administrative:true);$db->transaction(fn()=>(new Policies($db,$f['config']))->set('SERVICE',$id,['package_proration'=>'EXACT_SECONDS'],0,$staff));
    $product=$f['create']('product-create',['name'=>'Synthetic upgraded hosting','category_id'=>$f['category'],'product_type'=>'HOSTING','pricing_strategy'=>'FIXED_THEN_FX','source_currency'=>'USD','activation_policy'=>'AUTO','refund_policy'=>'staff_approval']);$f['create']('price-publish',['item_id'=>$product,'cycle_id'=>$f['cycle'],'currency'=>'USD','amount'=>'6']);$db->transaction(fn()=>$f['service']->execute('product-status',['id'=>$product,'version'=>1,'sale_status'=>'ACTIVE'],$f['actor'],Id::uuid()));$selection=['product_id'=>$product,'cycle_id'=>$f['cycle'],'quantity'=>1];$db->transaction(fn()=>$pools->mapSelection($product,$pool['pool'],'mock_upgraded','mock_reseller',$selection));$changes=new PackageChanges($db,$f['config']);return $f+compact('pool','engine','id','staff','selection','changes');
}
function fundPackage($db,array $f,array $change): void
{
    $order=$f['orders']->repository->find($change['order_id'],$f['customer']);$bill=$f['billing']->detail($order['payment_request_id'],$f['customer']);$money=new \Hostider\Finance\Money($bill['total_minor'],new \Hostider\Finance\Currency($bill['currency']));$db->transaction(function()use($f,$order,$money): void{$payment=$f['finance']->recordTestCollection($f['customer'],$money,Id::uuid(),$f['actor'],Id::uuid());$f['orders']->fund($order['id'],$f['customer'],$money,'COLLECTION',$payment,Id::uuid(),$f['actor'],Id::uuid());});
}
test('F3-E exact-second upgrade proration uses integer half-up without financial float',function(): void{same('51',PackageChanges::prorate('101',1,2));same('0',PackageChanges::prorate('99999999999999',0,30));same('10000000000000',PackageChanges::prorate('30000000000000',10,30));});
test('F3-E package upgrade requires paid fixed request and capability before verified same-resource change',function()use($db): void{
    $f=packageFixture($db);$before=$f['engine']->repository->find($f['id'],lock:false);$change=$f['changes']->request($f['id'],$f['customer'],$f['selection'],$f['staff'],Id::uuid(),new DateTimeImmutable('now',new DateTimeZone('UTC')));same(409,raises(HttpError::class,fn()=>$f['changes']->preparePaid($change['id'],$f['staff'],Id::uuid()))->status);same(409,raises(HttpError::class,fn()=>$f['engine']->discover($change['order_id'],$f['actor'],Id::uuid()))->status);fundPackage($db,$f,$change);$operation=$f['changes']->preparePaid($change['id'],$f['staff'],Id::uuid());$journals=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();same(true,(new Runner($db,$f['config']))->once($f['actor'],$operation));same(false,(new Runner($db,$f['config']))->once($f['actor'],$operation));$after=$f['engine']->repository->find($f['id'],lock:false);same($f['selection']['product_id'],$after['product_id']);same($before['current_period_id'],$after['current_period_id']);same('mock_upgraded',$db->execute('SELECT package_name FROM mock_hosting_accounts WHERE service_id=?',[$f['id']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$f['id']])->fetchColumn());same($journals,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());same('720',$db->execute('SELECT CAST(total_minor AS CHAR) FROM svc_prices WHERE id=?',[$after['current_price_id']])->fetchColumn());
});
test('F3-E missing package capability blocks dispatch and downgrade does not invent a credit policy',function()use($db): void{
    $f=packageFixture($db);$change=$f['changes']->request($f['id'],$f['customer'],$f['selection'],$f['staff'],Id::uuid(),new DateTimeImmutable('now',new DateTimeZone('UTC')));fundPackage($db,$f,$change);$db->execute("UPDATE hosting_servers SET capabilities='[\"inspectAccount\"]' WHERE id=?",[$f['pool']['server']]);same(409,raises(HttpError::class,fn()=>$f['changes']->preparePaid($change['id'],$f['staff'],Id::uuid()))->status);same(0,(int)$db->execute("SELECT COUNT(*) FROM svc_operations WHERE service_id=? AND kind='CHANGE_PACKAGE'",[$f['id']])->fetchColumn());$f['create']('price-publish',['item_id'=>$f['selection']['product_id'],'cycle_id'=>$f['cycle'],'currency'=>'USD','amount'=>'1']);same(409,raises(HttpError::class,fn()=>$f['changes']->plan($f['id'],$f['customer'],$f['selection'],$f['staff'],new DateTimeImmutable('now',new DateTimeZone('UTC'))))->status);
});
test('F3-E UNKNOWN paid package change resolves observed package without a second mutation',function()use($db): void{
    $f=packageFixture($db);$change=$f['changes']->request($f['id'],$f['customer'],$f['selection'],$f['staff'],Id::uuid(),new DateTimeImmutable('now',new DateTimeZone('UTC')));fundPackage($db,$f,$change);$operation=$f['changes']->preparePaid($change['id'],$f['staff'],Id::uuid());same(true,(new \Hostider\Services\ActionWorker($db,$f['config']))->once($operation,$f['actor'],'TIMEOUT_AFTER_CREATE'));same('UNKNOWN',$f['engine']->repository->find($f['id'],lock:false)['status']);$reconciliation=new \Hostider\Services\Reconciliation($db,$f['config']);$inspection=$reconciliation->inspect($f['id'],$f['customer'],$f['staff'],Id::uuid());same('ACTIVE',$reconciliation->resolve($f['id'],$f['customer'],$inspection['inspection_id'],$f['staff'],Id::uuid())['status']);same($f['selection']['product_id'],$f['engine']->repository->find($f['id'],lock:false)['product_id']);same(1,(int)$db->execute("SELECT COUNT(*) FROM mock_hosting_calls WHERE server_id=? AND action='changePackage'",[$f['pool']['server']])->fetchColumn());
});
runTests();
